UPDATE rfqhd
   SET PROGRESS_CD = 'J',
       MOD_DATE    = NOW(),
       MOD_USER_ID = #{loginUserId}
 WHERE RFQ_NUM = #{rfqNum}
   AND PROGRESS_CD = 'G'
   AND CTRL_USER_ID = #{loginUserId}
   AND DEL_FLAG = 'N'

UPDATE rfqvn
   SET SELECT_YN   = 'Y',
       MOD_DATE    = NOW(),
       MOD_USER_ID = #{loginUserId}
 WHERE RFQ_NUM = #{rfqNum}
